-- Creating a workspace puts the transaction in that workspace's scope.
-- The id is generated by the database (the column default), and the row level
-- security rules need the id in the scope before the row can be written or read
-- back, so the trigger sets it. It never overrides a scope that is already set:
-- a request acting inside one workspace cannot create another.
CREATE FUNCTION workspaces_enter_own_scope() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF app_workspace_id() IS NULL THEN
    PERFORM set_config('app.workspace_id', NEW.id::text, true);
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER workspaces_enter_own_scope
  BEFORE INSERT ON "workspaces"
  FOR EACH ROW EXECUTE FUNCTION workspaces_enter_own_scope();
